window.MM_DATA = [{"id":"q_20261107_03","group":"Awaiting result","when":"Fri Nov 20","q":"Will China's yttrium sales abroad fall by half in October?","cat":"Energy & climate","label":"China yttrium export flows","strength":"none","instrument":"Physical yttrium oxide prices","yes":{"dir":"up","head":"Physical yttrium prices","why":"A sharp drop in shipments can lift oxide prices if buyers run short. Listed rare-earth stocks have mixed mineral exposure."},"no":{"dir":"mixed","head":"Less risk of a yttrium shortage","why":"If export volumes hold up, the shortage case for physical yttrium oxide weakens. Listed rare-earth shares still have mixed exposure."},"caveat":"Few liquid equities have clean exposure to this specific material.","opt":""},{"id":"q_20261018_02","group":"Awaiting result","when":"Until Mon Nov 23","q":"Will America let Hungary keep buying Russian oil for six more months?","cat":"Geopolitics","label":"Hungary Russian oil exemption","strength":"linked","instrument":"MOL · Hungarian oil refiner shares","yes":{"dir":"up","head":"MOL shares","why":"An exemption can let MOL keep using Russian crude. Access to cheaper feedstock can support refining margins if the price discount holds."},"no":{"dir":"down","head":"MOL shares","why":"Without the exemption, MOL may need costlier replacement crude. That can compress its refining margins unless it passes the extra cost on."},"caveat":"Crude availability, local price controls and currency can offset the benefit.","opt":""},{"id":"q_20261025_05","group":"Awaiting result","when":"By Tue Nov 24","q":"Will Egypt put its economic plan to public debate within a month?","cat":"Politics","label":"Egypt economic policy consultation","strength":"proxy","instrument":"Egypt government bonds and the Egyptian pound","yes":{"dir":"up","head":"Egyptian bonds and pound","why":"A credible reform plan with financing can support government bonds and the pound. Opening a debate alone leaves the financing unchanged."},"no":{"dir":"down","head":"Egyptian bonds and pound","why":"Without a public debate, near-term policy clarity can fall. Egyptian bonds and the pound could weaken if financing or reform timelines slip as well."},"caveat":"A consultation can leave policy and financing unchanged.","opt":""},{"id":"q_20261031_03","group":"Today","when":"Wed Nov 25","q":"Will Volkswagen's first talks with its union end without a deal?","cat":"Markets & business","label":"Volkswagen union talks","strength":"linked","instrument":"Volkswagen preferred shares · VOW3","yes":{"dir":"down","head":"Volkswagen shares (VOW3)","why":"Failed talks can hurt VOW3 if they lead to strikes, lost car production, or higher labour costs."},"no":{"dir":"up","head":"Volkswagen shares (VOW3)","why":"A deal can reduce strike risk and support VOW3. Expensive wage or job guarantees can offset that relief."},"caveat":"A quick deal or wider auto rally could reverse the move.","opt":""},{"id":"q_20261022_52","group":"Today","when":"Wed Nov 25","q":"Will Brussels keep France's deficit case on hold this autumn?","cat":"Politics","label":"France deficit oversight","strength":"proxy","instrument":"French OATs vs German Bunds","yes":{"dir":"down","head":"French borrowing premium","why":"If the EU leaves France’s deficit case on hold, investors may demand a smaller premium to hold French debt over German debt."},"no":{"dir":"up","head":"French borrowing premium","why":"If the EU resumes its deficit procedure, the extra yield investors demand on French debt over German debt could widen."},"caveat":"A hold can be priced in and French politics can outweigh it.","opt":""},{"id":"q_20261018_03","group":"Today","when":"Wed Nov 25","q":"Will Korea's central bank hold off on raising rates in November?","cat":"Economy","label":"Korea rate-hold scenario","strength":"linked","instrument":"Korean 3-year government bonds","yes":{"dir":"up","head":"Korean bond prices","why":"If Korea holds rates when markets expect a hike, three-year yields can fall and bond prices can rise. Guidance can offset that move."},"no":{"dir":"down","head":"Korean bond prices","why":"If Korea raises rates, a larger-than-priced move can push three-year yields up and bond prices down."},"caveat":"An unchanged rate with hawkish guidance can push yields up.","opt":""},{"id":"q_20261030_01","group":"Today","when":"Wed Nov 25","q":"Will South Korea's central bank raise its growth forecast for next year?","cat":"Economy","label":"Korea growth forecast revision","strength":"proxy","instrument":"EWY · South Korea equities","yes":{"dir":"up","head":"South Korea stocks (EWY)","why":"A growth upgrade can lift Korean earnings expectations. EWY reflects the broader stock market, including large chipmakers."},"no":{"dir":"mixed","head":"EWY loses a demand boost","why":"If the growth forecast is unchanged or cut, EWY loses the upgrade as a demand catalyst. A cut can weigh on local earnings expectations."},"caveat":"A concentrated chip weighting and the won can dominate returns.","opt":"etf:ewy"},{"id":"q_20261123_01","group":"Tomorrow","when":"Thu Nov 26","q":"Will most Korean central bankers expect two more rate rises by spring?","cat":"Economy","label":"Korea rate-path expectations","strength":"linked","instrument":"Korean 3-year government bonds","yes":{"dir":"down","head":"Korean bond prices","why":"If Korea’s central bankers signal more hikes than markets expect, three-year yields can rise and bond prices can fall."},"no":{"dir":"up","head":"Korean bond prices","why":"If most bankers flag fewer hikes than markets expected, three-year yields can fall and bond prices can rise."},"caveat":"Weak growth can offset tighter guidance.","opt":""},{"id":"q_20261031_01","group":"Tomorrow","when":"Thu Nov 26","q":"Will electronics prices in Tokyo climb faster in November?","cat":"Economy","label":"Tokyo electronics prices","strength":"proxy","instrument":"CME yen futures · short-term Japanese yields","yes":{"dir":"up","head":"Japanese yen","why":"Faster electronics inflation can support the yen if it changes expectations for a Bank of Japan hike. One category often has little effect on its own."},"no":{"dir":"down","head":"Japanese yen","why":"If electronics inflation stays soft and broader inflation agrees, the yen can lose rate-hike support and short-term yields can ease."},"caveat":"A narrow category may move without changing monetary policy expectations.","opt":""},{"id":"q_20261111_03","group":"This week","when":"Until Fri Nov 27","q":"Will American and Iranian officials meet face to face within two weeks?","cat":"Geopolitics","label":"US–Iran diplomatic contact","strength":"proxy","instrument":"ICE Brent · near-month futures spread","yes":{"dir":"down","head":"Near-term Brent premium","why":"A meeting can take some supply risk out of near-term oil prices if it improves the odds of safe tanker transit."},"no":{"dir":"mixed","head":"Brent keeps more supply-risk premium","why":"Without a meeting, the diplomatic relief for near-month Brent is weaker. An actual increase in shipments can still pull the spread down."},"caveat":"A meeting can occur without any change in shipments.","opt":""},{"id":"q_20261031_02","group":"This week","when":"Fri Nov 27","q":"Will rising prices trigger Belgium's automatic pay and benefit rise next month?","cat":"Economy","label":"Belgian wage and benefit indexation","strength":"proxy","instrument":"Shares of labour-intensive Belgian companies","yes":{"dir":"down","head":"Margins at exposed Belgian employers","why":"Automatic wage rises raise payroll costs. Margins can shrink at companies that struggle to pass the increase on to customers."},"no":{"dir":"mixed","head":"Employers avoid the immediate wage increase","why":"Without the trigger, affected companies avoid that immediate payroll increase. Margins still depend on wages and pricing elsewhere."},"caveat":"Timing and sector rules can limit the immediate margin effect.","opt":""},{"id":"q_20261024_03","group":"This week","when":"Fri Nov 27","q":"Will an iPhone Duo ordered on Black Friday still miss Christmas?","cat":"Tech & science","label":"Apple holiday shipping lead times","strength":"linked","instrument":"AAPL and handset supply-chain data","yes":{"dir":"mixed","head":"Apple revenue could land later","why":"Late shipments can push some Apple revenue into a later period if enough Black Friday orders miss the quarter."},"no":{"dir":"mixed","head":"Apple avoids some risk of delayed sales","why":"If orders arrive on time, Apple avoids some risk of delayed sales recognition. Actual shipment volume determines how much that matters."},"caveat":"The revenue read-through depends on how many shipments slip.","opt":""},{"id":"q_20261105_04","group":"This week","when":"Fri Nov 27","q":"Will the index behind many Brazilian rents jump in November?","cat":"Economy","label":"Brazil rents and inflation index","strength":"proxy","instrument":"B3 DI1 interest-rate futures","yes":{"dir":"down","head":"Brazilian bond prices","why":"A big rent-index rise can lift expected Brazilian interest rates if it signals broader inflation. DI1 futures reflect those expectations."},"no":{"dir":"up","head":"Brazilian bond prices","why":"A smaller rise can ease rate-hike expectations if other inflation measures agree. Brazilian bond prices can benefit if expected yields fall."},"caveat":"One volatile index print is a weak proxy for the Selic path.","opt":""},{"id":"q_20261113_02","group":"This week","when":"Until Sat Nov 28","q":"Will Europeans join the Russia-Ukraine peace talks by late November?","cat":"Geopolitics","label":"European role in Ukraine talks","strength":"proxy","instrument":"ICE Dutch TTF natural gas futures","yes":{"dir":"down","head":"European gas (TTF)","why":"European participation could affect gas prices if it helps deliver a deal that changes supply. Attendance alone does little to gas flows."},"no":{"dir":"none","head":"No clear move in European gas","why":"If Europeans stay out, European gas loses one potential route to a supply deal. Prices could still fall if other parties agree on energy flows."},"caveat":"Attendance alone has a weak link to physical energy flows.","opt":""},{"id":"q_20261025_04","group":"This week","when":"Until Sat Nov 28","q":"Will Apple keep fixing cracked Duos one by one through Black Friday?","cat":"Tech & science","label":"Apple foldable repair policy","strength":"linked","instrument":"AAPL · Apple","yes":{"dir":"mixed","head":"Apple avoids a broader repair bill","why":"If Apple keeps handling repairs individually, warranty costs are likely to stay more contained than under a broad service programme."},"no":{"dir":"mixed","head":"Apple’s cost depends on what replaces repairs","why":"If the issue shifts to a broad repair programme, Apple’s warranty costs can rise. If the issue simply stops, that cost risk recedes."},"caveat":"A small number of repairs can have little impact on the company.","opt":""},{"id":"q_20261113_01","group":"This week","when":"Until Sun Nov 29","q":"Will America and Iran reach a deal within two weeks?","cat":"Geopolitics","label":"US–Iran deal scenario","strength":"proxy","instrument":"ICE Brent crude futures","yes":{"dir":"down","head":"Brent oil","why":"A deal that gets more tankers moving can ease supply fears and put downward pressure on Brent."},"no":{"dir":"up","head":"Brent oil","why":"Without a deal, the supply premium can hold or rise if shipping remains constrained. Continued tanker flows can soften Brent anyway."},"caveat":"Terms, timing and physical supply can diverge.","opt":""},{"id":"q_20261116_01","group":"This week","when":"Sun Nov 29","q":"Will the oil producers' group adopt its new quota system on schedule?","cat":"Energy & climate","label":"Producer quota rollout","strength":"proxy","instrument":"ICE Brent · near-month versus later futures","yes":{"dir":"mixed","head":"Brent spread depends on actual output","why":"A quota change can move the gap between near-term and later Brent prices if it changes how much oil arrives now."},"no":{"dir":"mixed","head":"Brent spread still follows supply","why":"If the rollout slips, new quota rules have less immediate effect on supply. Near-term Brent spreads could still move on actual production changes."},"caveat":"A schedule change can leave aggregate supply unchanged.","opt":""},{"id":"q_20261118_03","group":"Next week","when":"Mon Nov 30","q":"Will Indian banks' gold loans stop growing in October?","cat":"Markets & business","label":"Indian gold loan growth slowdown","strength":"proxy","instrument":"MUTHOOTFIN · Muthoot Finance","yes":{"dir":"down","head":"Muthoot shares","why":"Slower growth in Indian gold loans can mean fewer new loans and slower interest-income growth for specialists such as Muthoot Finance."},"no":{"dir":"up","head":"Muthoot shares","why":"If loan growth continues, a larger interest-earning book could help gold lenders such as Muthoot. Funding costs and defaults still matter."},"caveat":"Seasonal demand and regulatory changes can produce different equity effects.","opt":""},{"id":"q_20261110_01","group":"Next week","when":"Mon Nov 30","q":"Will Methanex hold or raise its Asian methanol price for December?","cat":"Energy & climate","label":"Methanex Asian contract pricing","strength":"linked","instrument":"MEOH · Methanex","yes":{"dir":"up","head":"Methanex shares (MEOH)","why":"A higher Asian methanol price can lift Methanex’s margins if contract selling prices rise faster than production costs."},"no":{"dir":"down","head":"Methanex shares (MEOH)","why":"A lower posted methanol price can squeeze Methanex’s margins if realized selling prices follow and feedstock costs stay high."},"caveat":"Discounts, natural gas costs and production disruptions can outweigh the posted price.","opt":"stocks:meoh"},{"id":"q_20261105_02","group":"Next week","when":"Until Mon Nov 30","q":"Will America extend its Ebola entry ban on green card holders?","cat":"Tech & science","label":"U.S. entry policy update","strength":"none","instrument":"Passenger demand on affected routes","yes":{"dir":"none","head":"No clear move in airline shares","why":"The entry restriction can reduce some trips, but its scope is too narrow to single out a listed airline exposure."},"no":{"dir":"none","head":"No clear move in airline shares","why":"If the restriction ends, the narrow group of affected passengers can resume travel. The change is too small on its own to isolate an airline trade."},"caveat":"An immigration rule may have little impact on travel demand.","opt":""},{"id":"q_20261103_03","group":"Next week","when":"Mon Nov 30","q":"Will computer memory chips cost even more this month?","cat":"Tech & science","label":"Memory chip pricing","strength":"linked","instrument":"MU · Micron","yes":{"dir":"up","head":"Micron shares (MU)","why":"Rising memory-chip contract prices can lift Micron’s sales and margins if it can sell the same mix and volume."},"no":{"dir":"down","head":"Micron shares (MU)","why":"If chip prices level off or fall, Micron gets less help from pricing. Greater shipments or a more profitable product mix can still support MU."},"caveat":"Product mix, inventory and prior repricing can offset spot gains.","opt":"stocks:mu"},{"id":"q_20261028_04","group":"Next week","when":"Mon Nov 30","q":"Will Apple keep selling the iPhone Duo through Black Friday?","cat":"Tech & science","label":"Apple handset availability","strength":"linked","instrument":"AAPL and retail inventory","yes":{"dir":"mixed","head":"Apple keeps its chance to make sales","why":"Keeping the device on sale preserves an opportunity for Apple revenue. Actual sales and shipments determine how much it is worth."},"no":{"dir":"down","head":"Apple’s sales from the device","why":"If Apple stops selling the device, the opportunity for new sales shrinks unless buyers shift to another Apple model."},"caveat":"Ongoing listings do not establish strong demand or fulfilled orders.","opt":""},{"id":"q_20261025_02","group":"Next week","when":"Mon Nov 30","q":"Will Cyber Monday computer deals shrink sharply from last year?","cat":"Economy","label":"Cyber Monday PC discounting","strength":"proxy","instrument":"DELL · BBY · PC makers and electronics retailers","yes":{"dir":"mixed","head":"Retailers gain on price if sales hold up","why":"Shallower PC discounts can help margins when shoppers still buy. If shoppers walk away, fewer units can offset the higher selling price."},"no":{"dir":"mixed","head":"Retailers trade lower margins for more volume","why":"If retailers keep discounts deep, they can sell more units at lower margins. DELL or BBY can benefit if the extra volume outweighs the price cuts."},"caveat":"Narrower discounts may reflect healthy demand or weak promotional activity.","opt":""},{"id":"q_20261114_01","group":"Next week","when":"Tue Dec 1","q":"Will Russia's official oil price fall by over a third in November?","cat":"Energy & climate","label":"Russian oil price discount","strength":"proxy","instrument":"Urals vs Brent price spread","yes":{"dir":"down","head":"Urals oil vs Brent","why":"A lower Russian oil price can widen the discount of Urals crude to Brent. Brent itself can move in either direction."},"no":{"dir":"mixed","head":"Less pressure on Urals vs Brent","why":"If Russia’s official price holds up, the expected widening in the Urals discount loses support. Actual cargo quotes matter more to the spread."},"caveat":"A local discount can widen while world crude prices rise.","opt":""},{"id":"q_20261118_01","group":"Next week","when":"Tue Dec 1","q":"Will Qatar hold or raise its sulfur price for next month?","cat":"Energy & climate","label":"Qatar sulfur export price","strength":"proxy","instrument":"Sulfur and phosphate fertilizer prices","yes":{"dir":"down","head":"Phosphate producers’ margins","why":"Higher Qatari sulfur prices raise input costs for phosphate producers that buy sulfur at linked prices."},"no":{"dir":"up","head":"Phosphate producers’ margins","why":"A lower Qatari sulfur price can ease costs for phosphate producers linked to that price, supporting margins if fertilizer prices hold."},"caveat":"Pass-through can vary and firms may have existing input contracts.","opt":""},{"id":"q_20261102_01","group":"Next week","when":"Tue Dec 1","q":"Will Brazil buy more wheat from Argentina this November than last?","cat":"Energy & climate","label":"Brazil wheat import flows","strength":"proxy","instrument":"Argentine wheat export prices · CME wheat futures","yes":{"dir":"up","head":"Argentine wheat prices","why":"More Brazilian buying can firm Argentine wheat prices. Chicago futures are exposed only through the wider grain market."},"no":{"dir":"mixed","head":"Argentine wheat loses a possible buyer","why":"If Brazil buys the same amount or less, Argentine export prices lose a possible source of support. Chicago wheat can trade on other supply news."},"caveat":"Bilateral flows can shift while global wheat demand stays flat.","opt":""},{"id":"q_20261023_02","group":"Next week","when":"Tue Dec 1","q":"Will Colombia's dams end November emptier than in the last El Niño?","cat":"Energy & climate","label":"Colombian reservoir levels","strength":"proxy","instrument":"Colombian wholesale power and hydro producers","yes":{"dir":"up","head":"Colombian power prices","why":"Low reservoirs can force Colombia to run more expensive thermal plants, lifting power prices and cutting output at hydro producers."},"no":{"dir":"down","head":"Colombian power prices","why":"If reservoir levels hold up, cheaper hydro can supply more of the grid. That can ease wholesale prices and support hydro generation volumes."},"caveat":"Regulated tariffs and hedges can mute the spot-price read-through.","opt":""},{"id":"q_20261021_25","group":"Next week","when":"Until Tue Dec 1","q":"Will Tesla and SpaceX reach December without a merger deal?","cat":"Markets & business","label":"Tesla and SpaceX merger speculation","strength":"linked","instrument":"TSLA · Tesla","yes":{"dir":"mixed","head":"Tesla shares could move either way","why":"If the companies go into December without a merger, Tesla avoids near-term financing and dilution risk from a deal. Shares can still lose any premium from merger speculation."},"no":{"dir":"mixed","head":"Tesla shares depend on deal terms","why":"If a deal is announced, TSLA can react to the price, ownership and financing terms. A costly deal can weigh on shares even if some investors like the combination."},"caveat":"An absence of a merger can already be priced and broader Tesla factors dominate.","opt":""},{"id":"q_20261102_04","group":"Next week","when":"Wed Dec 2","q":"Will lawmakers pass South Korea's record budget on time?","cat":"Politics","label":"South Korea budget passage","strength":"proxy","instrument":"Korean government bonds","yes":{"dir":"mixed","head":"Bond impact depends on new borrowing","why":"The budget can affect bond prices if it changes how much debt Korea needs to issue. Passing it on schedule may change little."},"no":{"dir":"mixed","head":"Bond impact depends on when debt is sold","why":"If passage slips, the timing of Korean debt sales can change. The effect on yields depends on whether issuance is postponed or simply rescheduled."},"caveat":"Timely passage can already be priced and sector effects depend on allocations.","opt":""},{"id":"q_20261029_02","group":"Next week","when":"Until Thu Dec 3","q":"Will Hong Kong have to defend its currency before December?","cat":"Markets & business","label":"Hong Kong currency defense","strength":"linked","instrument":"USD/HKD · Hong Kong interbank rates","yes":{"dir":"up","head":"Hong Kong interbank rates","why":"At the weak edge of the peg, official purchases of Hong Kong dollars can drain cash from banks and lift local short-term borrowing rates."},"no":{"dir":"mixed","head":"Less intervention pressure on rates","why":"If the currency stays within the band without intervention, official reserve transactions add less pressure to local short-term rates."},"caveat":"The currency band limits spot upside from a weak-side test.","opt":""},{"id":"q_20261029_03","group":"Next week","when":"Thu Dec 3","q":"Will Scotland raise tax on landlords' rent as much as England?","cat":"Politics","label":"Scottish rental income tax","strength":"none","instrument":"UK landlords with Scottish residential exposure","yes":{"dir":"down","head":"Affected landlords’ rental income","why":"Higher taxes can squeeze affected landlords’ returns. The stock connection depends on whether the adopted rules cover companies."},"no":{"dir":"mixed","head":"Less pressure on landlords’ rental income","why":"A smaller tax rise reduces the expected hit to landlords’ net rental income. The listed impact still hinges on who the rules cover."},"caveat":"Individual tax rules can have a different effect on corporate landlords.","opt":""},{"id":"q_20261026_03","group":"Next week","when":"Until Thu Dec 3","q":"Will Volkswagen's board hold off approving Audi's Georgia factory into December?","cat":"Markets & business","label":"Audi Georgia factory decision","strength":"linked","instrument":"VOW3 · Volkswagen preferred shares","yes":{"dir":"mixed","head":"Volkswagen could conserve cash","why":"Delaying the factory can preserve near-term cash for Volkswagen while pushing back expected US production for Audi."},"no":{"dir":"mixed","head":"VW spends earlier and gains a clearer growth path","why":"If the board approves the factory sooner, Volkswagen can face earlier spending while gaining a clearer path to Audi’s US production."},"caveat":"A delayed factory can conserve near-term cash while lowering future capacity.","opt":""},{"id":"q_20261123_04","group":"Next week","when":"Fri Dec 4","q":"Will governments adopt a global carbon price for ships next week?","cat":"Energy & climate","label":"Shipping carbon levy","strength":"proxy","instrument":"Shipping freight rates and shipping stocks","yes":{"dir":"up","head":"Shipping rates","why":"A carbon levy raises fuel-related shipping costs. Freight rates can rise when carriers can pass that cost to customers."},"no":{"dir":"mixed","head":"Freight avoids the new carbon cost","why":"Without a levy, that extra fuel-related cost stays out of freight pricing. Rates can still rise if cargo demand outstrips ship availability."},"caveat":"Phase-in timing and exemptions may make the near-term impact small.","opt":""},{"id":"q_20261120_01","group":"Next week","when":"Until Fri Dec 4","q":"Will California's tax withheld from November pay jump sharply from last year?","cat":"Economy","label":"California payroll tax receipts","strength":"proxy","instrument":"California municipal bonds","yes":{"dir":"up","head":"California bond prices","why":"Sustained gains in payroll tax receipts can improve the state’s budget outlook, helping its borrowing costs relative to peers."},"no":{"dir":"down","head":"California bond prices","why":"If the receipts miss expectations, the state gets less evidence of a stronger tax base. California borrowing spreads could widen if the weakness persists."},"caveat":"Bonus timing or tax-base swings can dominate one month.","opt":""},{"id":"q_20261024_04","group":"Next week","when":"Until Fri Dec 4","q":"Will Blue Origin's big rocket stay grounded into December?","cat":"Tech & science","label":"Blue Origin launch delay","strength":"none","instrument":"Payload customers and alternative launch providers","yes":{"dir":"mixed","head":"Rival launch providers could gain work","why":"A longer delay can shift launch schedules or contracts. Blue Origin is privately held, so any listed exposure depends on the affected customer or supplier."},"no":{"dir":"mixed","head":"Less work may shift to rivals","why":"If the rocket returns, customers face fewer delays and alternative launch providers lose some potential diverted work."},"caveat":"Blue Origin event exposure is indirect through public peers.","opt":""},{"id":"q_20261106_01","group":"Next week","when":"Fri Dec 4","q":"Will Taiwan's foreign currency reserves shrink again in November?","cat":"Markets & business","label":"Taiwan FX reserve trend","strength":"proxy","instrument":"USD/TWD · US dollar vs Taiwan dollar","yes":{"dir":"mixed","head":"USD/TWD depends on why reserves fell","why":"Reserves can fall when Taiwan’s central bank sells US dollars to support the Taiwan dollar. A stronger US dollar can also change the reported reserve value."},"no":{"dir":"mixed","head":"Less evidence of dollar selling","why":"Stable or rising reserves ease the case for reserve loss or dollar-selling pressure. USD/TWD can still move on trade flows and global dollar strength."},"caveat":"Dollar strength can change reserve values on its own.","opt":""},{"id":"q_20261107_02","group":"Next week","when":"Fri Dec 4","q":"Will America's construction jobs jump in November?","cat":"Economy","label":"U.S. construction payrolls","strength":"proxy","instrument":"CME 10-Year Treasury Note futures","yes":{"dir":"down","head":"US Treasury note futures","why":"A construction jobs jump can push yields higher if it changes the broader jobs picture and rate expectations. Treasury futures then tend to fall."},"no":{"dir":"up","head":"US Treasury note futures","why":"If hiring misses expectations and the broader jobs report cools too, Treasury yields can fall and note futures can rise."},"caveat":"Weather and survey noise can produce a one-month jump.","opt":""},{"id":"q_20261112_02","group":"Next week","when":"Sat Dec 5","q":"Will Russia and Ukraine swap a thousand prisoners each by early December?","cat":"Geopolitics","label":"Russia–Ukraine prisoner exchange","strength":"none","instrument":"European gas and wheat prices are distant proxies","yes":{"dir":"none","head":"No clear move in gas or wheat","why":"A prisoner exchange can show talks are progressing. Gas and wheat supply change only if separate agreements affect shipping or energy flows."},"no":{"dir":"none","head":"No clear move in gas or wheat","why":"If the exchange goes nowhere, the diplomatic signal weakens. Gas or wheat prices would need separate news about supply or transit to react meaningfully."},"caveat":"The exchange has a weak direct connection to tradable supply.","opt":""},{"id":"q_20261124_01","group":"Next week","when":"Sun Dec 6","q":"Will Saudi Arabia cut January oil prices for Asia more than Europe?","cat":"Energy & climate","label":"Saudi crude pricing by region","strength":"proxy","instrument":"Dubai crude vs Brent","yes":{"dir":"down","head":"Dubai oil vs Brent","why":"A bigger Saudi price cut for Asia can point to weaker regional buying and weigh on Dubai crude relative to Brent."},"no":{"dir":"mixed","head":"Less pressure on Dubai oil vs Brent","why":"If Asian discounts are no larger, the pricing decision gives less reason for Dubai crude to weaken against Brent. Freight and refinery demand can still move the spread."},"caveat":"One official selling-price decision can reflect market-share strategy.","opt":""},{"id":"q_20261110_02","group":"Dec 7–13","when":"Mon Dec 7","q":"Will Russia export at least three-quarters of its planned diesel this month?","cat":"Energy & climate","label":"Russian diesel exports","strength":"proxy","instrument":"ICE gasoil vs Brent","yes":{"dir":"down","head":"European diesel vs crude","why":"If Russia ships most of its planned diesel and those cargoes reach buyers, extra supply could weaken gasoil relative to Brent."},"no":{"dir":"up","head":"European diesel vs crude","why":"If Russia ships less than planned, tighter European diesel supply can widen the gasoil premium over Brent."},"caveat":"Freight, sanctions and inventories can absorb the extra supply.","opt":""},{"id":"q_20261104_01","group":"Dec 7–13","when":"Until Mon Dec 7","q":"Will Poland's central bank raise its gold target by early December?","cat":"Economy","label":"Poland central-bank gold allocation","strength":"proxy","instrument":"Gold spot and futures","yes":{"dir":"up","head":"Gold","why":"A higher reserve target can add demand for gold once Poland starts buying. The target alone sets no purchase date."},"no":{"dir":"mixed","head":"Gold loses a possible buyer","why":"Without a higher target, gold loses the potential demand from additional planned Polish buying. Other central banks can still drive demand."},"caveat":"A target change does not establish when purchases happen.","opt":""},{"id":"q_20261104_03","group":"Dec 7–13","when":"Mon Dec 7","q":"Will Australia's central bank raise rates again before Christmas?","cat":"Economy","label":"Australia rate decision","strength":"linked","instrument":"Australian 3-year government bonds","yes":{"dir":"down","head":"Australian bond prices","why":"An RBA hike above expectations can push three-year Australian yields up and bond prices down."},"no":{"dir":"up","head":"Australian bond prices","why":"A hold can pull three-year yields down and bond prices up if markets had priced a hike. Hawkish guidance can limit that relief."},"caveat":"A fully priced hike or softer guidance can drive yields lower.","opt":""},{"id":"q_20261124_04","group":"Dec 7–13","when":"Tue Dec 8","q":"Will Russia's crude oil shipments by sea keep climbing into December?","cat":"Energy & climate","label":"Russian crude loadings","strength":"proxy","instrument":"ICE Brent crude futures","yes":{"dir":"down","head":"Brent oil","why":"More Russian crude reaching buyers adds to available supply and can weigh on Brent."},"no":{"dir":"up","head":"Brent oil","why":"If loadings stop climbing, the extra supply pressure on Brent fades. If deliveries actually fall, Brent can get support."},"caveat":"Floating storage and demand changes can offset extra loadings.","opt":""},{"id":"q_20261103_01","group":"Dec 7–13","when":"Until Tue Dec 8","q":"Will Korea pay its refiners less than half what they claim?","cat":"Energy & climate","label":"Korean refiner compensation","strength":"linked","instrument":"Korean refiner shares","yes":{"dir":"down","head":"Korean refiner shares","why":"If compensation is below half the claim and below what refiners booked, they may need to take a write-down. That can weigh on their shares."},"no":{"dir":"up","head":"Korean refiner shares","why":"A larger payment can reduce the write-down risk or improve cash recovery for a refiner, depending on what it already booked."},"caveat":"A smaller settlement may already have been written down.","opt":""},{"id":"q_20261124_05","group":"Dec 7–13","when":"Until Wed Dec 9","q":"Will Europe keep the option to pause its carbon tax on imports?","cat":"Energy & climate","label":"EU carbon border flexibility","strength":"proxy","instrument":"EU carbon allowances and European steel shares","yes":{"dir":"down","head":"European steelmakers’ shares","why":"Pausing the border carbon charge can make imports cheaper for European steel buyers and put pressure on local steelmakers."},"no":{"dir":"up","head":"European steelmakers’ shares","why":"If the EU drops the pause option, the charge is more likely to stay in place. That can support local steelmakers relative to importers if import costs rise."},"caveat":"Border rules and the allowance price respond to different drivers.","opt":""},{"id":"q_20261121_01","group":"Dec 7–13","when":"Wed Dec 9","q":"Will Oracle lower its planned spending on data centers this year?","cat":"Tech & science","label":"Oracle data-center spending","strength":"linked","instrument":"ORCL · Oracle","yes":{"dir":"mixed","head":"Oracle shares could move either way","why":"If Oracle cuts spending because it can build capacity more cheaply, improved cash flow could help ORCL. A cut driven by weak demand could weigh on the shares instead."},"no":{"dir":"mixed","head":"Higher spending, with demand still key","why":"If Oracle keeps spending plans intact, near-term cash outflows stay higher. ORCL can still benefit if bookings show demand for the capacity."},"caveat":"The same capex cut can lift free cash flow or signal slower growth.","opt":""},{"id":"q_20261118_02","group":"Dec 7–13","when":"Until Wed Dec 9","q":"Will a top forecaster cut Russia's wheat export outlook over the bridge?","cat":"Energy & climate","label":"Russian wheat exports and logistics","strength":"proxy","instrument":"Chicago wheat futures","yes":{"dir":"up","head":"Chicago wheat futures","why":"A smaller Russian crop export forecast can tighten Black Sea wheat supply and lift Chicago wheat prices through global trade."},"no":{"dir":"down","head":"Chicago wheat futures","why":"If the Russian export outlook holds, the case for tighter Black Sea supply weakens. Chicago wheat can give back scarcity gains."},"caveat":"US wheat is an imperfect proxy for Black Sea grades and freight.","opt":""},{"id":"q_20261029_04","group":"Dec 7–13","when":"Until Wed Dec 9","q":"Will the race to replace Lagarde run past early December?","cat":"Economy","label":"ECB succession timing","strength":"proxy","instrument":"Euro-area rate swaps · EUR/USD","yes":{"dir":"none","head":"No clear direction for euro rates","why":"The succession matters to rates and the euro when it changes expectations for ECB policy. A delay by itself says little about rates."},"no":{"dir":"mixed","head":"EUR/USD depends on the appointee","why":"An earlier succession decision can move euro rates or EUR/USD if the named candidate changes expectations about policy."},"caveat":"A delayed appointment can have a weak market effect.","opt":""},{"id":"q_20261111_02","group":"Dec 7–13","when":"Wed Dec 9","q":"Will the Fed double its usual rate hike in December?","cat":"Economy","label":"Fed outsized hike scenario","strength":"linked","instrument":"Fed Funds futures · SHY Treasury ETF","yes":{"dir":"down","head":"Short-term Treasury ETF (SHY)","why":"Fed Funds futures reflect the policy rate. A larger-than-expected hike can lift short-term yields and weigh on SHY."},"no":{"dir":"up","head":"Short-term Treasury ETF (SHY)","why":"A smaller move can bring short-term yields down and support SHY if markets had priced a larger hike. A small hike can still be hawkish if guidance tightens."},"caveat":"A later easing repricing or shallow price sensitivity can dominate.","opt":"etf:shy"},{"id":"q_20261030_03","group":"Dec 7–13","when":"Wed Dec 9","q":"Will America's central bank raise interest rates again in December?","cat":"Economy","label":"Fed hike scenario","strength":"linked","instrument":"Fed Funds futures · TLT Treasury ETF","yes":{"dir":"down","head":"Long Treasury ETF (TLT)","why":"Fed Funds futures reflect the policy rate. TLT can fall if the hike also pushes long-term Treasury yields higher."},"no":{"dir":"up","head":"Long Treasury ETF (TLT)","why":"In a no-hike outcome, Fed Funds futures can rise if a hike was priced. TLT can gain if long-term Treasury yields also fall."},"caveat":"Long yields can fall after a hike. Treasury ETF prices also respond to inflation and term premiums.","opt":"etf:tlt"},{"id":"q_20261106_02","group":"Dec 7–13","when":"Thu Dec 10","q":"Will Hong Kong's biggest bank raise its main lending rate next month?","cat":"Economy","label":"Hong Kong bank lending rate","strength":"linked","instrument":"HSBC shares · Hong Kong lending rates","yes":{"dir":"mixed","head":"HSBC’s margin depends on deposit costs","why":"A prime-rate hike can raise interest collected on loans. HSBC’s margin can still narrow if it has to pay more for deposits."},"no":{"dir":"mixed","head":"HSBC misses a loan-rate boost","why":"If the lender leaves its prime rate unchanged, it misses the loan-yield uplift. Lower deposit costs can still improve margins."},"caveat":"A higher prime rate can hurt credit demand as well as raise yields.","opt":""},{"id":"q_20261122_05","group":"Dec 7–13","when":"Thu Dec 10","q":"Will gold be above 3,500 dollars the day after the Fed decides?","cat":"Energy & climate","label":"Gold after the Fed decision","strength":"linked","instrument":"Spot gold · CME gold futures · GLD","yes":{"dir":"up","head":"Gold futures and GLD","why":"If spot gold clears $3,500 on the specified day, that can support GLD and gold futures. How much they move depends on what buyers had already priced in."},"no":{"dir":"mixed","head":"Gold misses the $3,500 threshold","why":"If spot gold stays at or below $3,500 on the specified day, the upside threshold is missed. GLD and gold futures can still move differently over their own pricing windows."},"caveat":"The forecast has a specific spot-price threshold and date. GLD’s payoff depends on its own price and, for options, expiry.","opt":"etf:gld"},{"id":"q_20261102_05","group":"Dec 7–13","when":"Until Fri Dec 11","q":"Will Canada's trade fight with America drag on into mid-December?","cat":"Geopolitics","label":"Canada–U.S. tariff dispute","strength":"proxy","instrument":"Canadian dollar · exporters facing tariffs","yes":{"dir":"down","head":"Canadian dollar","why":"A longer tariff dispute can hurt exposed Canadian exporters and weigh on the Canadian dollar if growth expectations fall."},"no":{"dir":"up","head":"Canadian dollar","why":"A resolution that removes tariffs can ease pressure on affected exporters and support CAD if it improves Canada’s growth outlook."},"caveat":"CAD can respond more to oil and rate differentials than to the headlines.","opt":""},{"id":"q_20261101_01","group":"Dec 7–13","when":"Fri Dec 11","q":"Will Turkey's yearly deficit with the world shrink in October?","cat":"Economy","label":"Turkey current-account trajectory","strength":"proxy","instrument":"Turkish lira forwards and government bonds","yes":{"dir":"up","head":"Turkish lira and government bonds","why":"A smaller external deficit can reduce Turkey’s need for foreign funding. That can support the lira and sovereign debt if inflation stays in check."},"no":{"dir":"down","head":"Turkish lira and government bonds","why":"If the deficit fails to narrow, Turkey can remain more dependent on foreign financing, putting pressure on the lira and sovereign bonds."},"caveat":"Inflation, policy credibility and carry can dominate currency returns.","opt":""},{"id":"q_20261116_04","group":"Dec 7–13","when":"Fri Dec 11","q":"Will Russia pump noticeably less oil in November than in October?","cat":"Energy & climate","label":"Russian oil production","strength":"proxy","instrument":"ICE Brent crude futures","yes":{"dir":"up","head":"Brent oil","why":"Less Russian oil production can lift Brent if fewer barrels reach buyers and other suppliers leave the gap open."},"no":{"dir":"mixed","head":"Brent loses a source of support","why":"If Russia keeps output up and exports hold, the expected supply tightening fades and Brent can lose support."},"caveat":"Stock drawdowns or offsetting producer supply can mute the effect.","opt":""},{"id":"q_20261105_03","group":"Dec 7–13","when":"Fri Dec 11","q":"Will phone prices in Brazil rise in November?","cat":"Economy","label":"Brazil smartphone pricing","strength":"proxy","instrument":"Brazilian electronics retailers","yes":{"dir":"mixed","head":"Retail margins could move either way","why":"Higher phone prices can squeeze unit sales or help margins. The effect hinges on whether wholesale costs rose too."},"no":{"dir":"mixed","head":"Lower prices could help unit sales","why":"If phone prices stay flat or fall, retailers get less revenue per device. Better sales volumes or lower purchase costs can make up for it."},"caveat":"Higher prices can reflect weaker currency and lower unit demand.","opt":""},{"id":"q_20261109_02","group":"Dec 7–13","when":"Until Sat Dec 12","q":"Will America and Iran agree to reopen Hormuz within a month?","cat":"Geopolitics","label":"Hormuz reopening scenario","strength":"proxy","instrument":"ICE Brent crude futures","yes":{"dir":"down","head":"Brent oil","why":"A reopening that restores tanker traffic can remove some of the oil supply premium built into Brent."},"no":{"dir":"mixed","head":"Brent keeps more supply-risk premium","why":"Without an agreement, Brent can keep its supply premium if tanker traffic stays restricted. A recovery in flows would weaken the link."},"caveat":"Paper agreements can fail to restore flows and hedge costs can be high.","opt":""},{"id":"q_20261116_03","group":"Dec 14–20","when":"Tue Dec 15","q":"Will India import more gold in November than in October?","cat":"Energy & climate","label":"India physical gold demand","strength":"proxy","instrument":"Indian physical gold premium vs world spot","yes":{"dir":"up","head":"India’s local gold premium","why":"More imports can be a sign of stronger Indian demand. The local premium over world spot shows whether buyers are paying up for gold."},"no":{"dir":"down","head":"India’s local gold premium","why":"If imports are flat or lower and local premiums fall, the case for stronger physical gold demand in India weakens."},"caveat":"Holiday timing, customs and inventories can drive import totals.","opt":""},{"id":"q_20261114_02","group":"Dec 14–20","when":"Wed Dec 16","q":"Will Indonesia's central bank raise interest rates in December?","cat":"Economy","label":"Indonesia rate decision","strength":"linked","instrument":"Indonesian front-end government bonds","yes":{"dir":"down","head":"Indonesian bond prices","why":"An unexpected Bank Indonesia hike can push short-dated government bond yields up and prices down."},"no":{"dir":"up","head":"Indonesian bond prices","why":"A hold can lower local short-term yields and support bonds if investors had expected a hike. Currency pressure can limit the bond move."},"caveat":"A stabilizing rupiah can attract bond buyers and offset the rate shock.","opt":""},{"id":"q_20261114_03","group":"Dec 14–20","when":"Until Thu Dec 17","q":"Will European officials join the next round of Ukraine peace talks?","cat":"Geopolitics","label":"European participation in peace talks","strength":"proxy","instrument":"ICE Dutch TTF natural gas futures","yes":{"dir":"down","head":"European gas (TTF)","why":"Peace talks can affect European gas prices if they improve the odds of a deal that changes supply. A seat at the talks alone has little market effect."},"no":{"dir":"none","head":"No clear move in European gas","why":"Without European participation, gas prices have less reason to react to the delegation alone. Actual transit or ceasefire news can still move TTF."},"caveat":"Weather and storage levels can dominate a diplomatic headline.","opt":""},{"id":"q_20261110_03","group":"Dec 14–20","when":"Thu Dec 17","q":"Will Texas move to let paused data centers switch on before Christmas?","cat":"Tech & science","label":"Texas data-center energization","strength":"proxy","instrument":"ERCOT power futures and forwards","yes":{"dir":"up","head":"Texas forward power prices","why":"New data centres can increase Texas electricity demand. The biggest price effect comes when projects connect to tight parts of the grid."},"no":{"dir":"down","head":"Texas forward power prices","why":"If the centres stay off the grid, near-term power demand is lower than in the restart scenario. Local forward prices could lose support."},"caveat":"Queue progress can be months away from actual electricity demand.","opt":""},{"id":"q_20261105_01","group":"Dec 14–20","when":"Thu Dec 17","q":"Will Taiwan raise interest rates next month?","cat":"Economy","label":"Taiwan rate decision","strength":"linked","instrument":"Taiwan front-end government bonds","yes":{"dir":"down","head":"Taiwan bond prices","why":"A Taiwan rate hike above expectations can push short-dated local yields up and bond prices down."},"no":{"dir":"up","head":"Taiwan bond prices","why":"A hold can lower short-dated yields and lift bond prices if investors had priced a hike. The guidance may matter more than the decision."},"caveat":"Liquidity and fully priced tightening can blunt the move.","opt":""},{"id":"q_20261106_03","group":"Dec 14–20","when":"Thu Dec 17","q":"Will the Bank of England raise rates again before Christmas?","cat":"Economy","label":"Bank of England rate decision","strength":"linked","instrument":"UK 2-year gilts","yes":{"dir":"down","head":"UK gilt prices","why":"An unexpected Bank of England hike can put upward pressure on two-year gilt yields and downward pressure on bond prices."},"no":{"dir":"up","head":"UK gilt prices","why":"A hold can pull two-year gilt yields down and prices up if markets had priced a hike. Firm rate guidance can limit the move."},"caveat":"A softer growth outlook can reverse the initial yield move.","opt":""},{"id":"q_20261107_01","group":"Dec 14–20","when":"Thu Dec 17","q":"Will mortgage rates be higher in mid-December than they are now?","cat":"Economy","label":"Higher U.S. mortgage rates","strength":"proxy","instrument":"ITB · U.S. homebuilders ETF","yes":{"dir":"down","head":"Homebuilder stocks (ITB)","why":"Higher mortgage rates tend to reduce buyer affordability. ITB tracks builders whose sales and margins can feel that pressure."},"no":{"dir":"up","head":"Homebuilder stocks (ITB)","why":"If mortgage rates stay flat or fall, buyer affordability can stabilize or improve, supporting ITB if sales follow."},"caveat":"Builder rate buydowns and housing supply shortages can support sales.","opt":"etf:itb"},{"id":"q_20261124_02","group":"Dec 14–20","when":"Until Fri Dec 18","q":"Will China take new steps against American companies by mid-December?","cat":"Geopolitics","label":"China restrictions on U.S. firms","strength":"none","instrument":"Stocks named in China’s announcement","yes":{"dir":"down","head":"Shares of companies China targets","why":"The exposure depends on which companies are targeted and what restrictions apply. A broad US stock index would dilute the effect."},"no":{"dir":"mixed","head":"Targeted shares avoid a new hit","why":"Without new restrictions, there is no new company-level sales hit from this decision. Existing restrictions can still weigh on affected shares."},"caveat":"A broad index can have little exposure to the specific firms named.","opt":""},{"id":"q_20261123_02","group":"Dec 14–20","when":"Until Fri Dec 18","q":"Will a big Chinese cloud company raise AI computing prices before mid-December?","cat":"Tech & science","label":"Chinese cloud compute pricing","strength":"none","instrument":"Shares of the Chinese cloud provider that raises prices","yes":{"dir":"up","head":"Revenue at the provider raising prices","why":"A higher GPU rental price helps that provider’s revenue if customers keep renting. The company remains unspecified in the question."},"no":{"dir":"mixed","head":"Cloud customers avoid a price increase","why":"If none of the big providers raises prices, suppliers lose a near-term pricing lift. Stable rental prices can help customers’ compute costs."},"caveat":"A price increase can come from capacity costs or constrained supply.","opt":""},{"id":"q_20261109_01","group":"Dec 14–20","when":"Until Fri Dec 18","q":"Will the final defense bill limit sales of chipmaking machines to China?","cat":"Geopolitics","label":"Chip-tool export restrictions","strength":"linked","instrument":"AMAT · Applied Materials","yes":{"dir":"down","head":"Applied Materials shares (AMAT)","why":"Tighter chip-tool export rules can reduce Applied Materials’ sales if the final text covers products it currently sells into China."},"no":{"dir":"mixed","head":"AMAT avoids a new sales hit","why":"Without new limits on those machines, AMAT avoids this additional hit to its China sales. Existing restrictions and order delays can still weigh on the stock."},"caveat":"Waivers, product mix and investment elsewhere can offset lost sales.","opt":"stocks:amat"},{"id":"q_20261121_03","group":"Dec 14–20","when":"Until Sat Dec 19","q":"Will Washington approve the sale of Lukoil's foreign business by mid-December?","cat":"Geopolitics","label":"Lukoil overseas asset sale","strength":"none","instrument":"Shares or debt of the eventual buyer","yes":{"dir":"mixed","head":"Buyer’s shares depend on deal terms","why":"Approval can change what the buyer pays and which assets it gets. The market connection depends on the buyer and sale terms."},"no":{"dir":"mixed","head":"Buyer avoids cost and forgoes earnings","why":"Without approval, an announced buyer avoids the immediate acquisition cost but also loses the assets and any earnings they would add."},"caveat":"Regulatory approval can leave material sanctions or financing conditions.","opt":""},{"id":"q_20261121_04","group":"Dec 14–20","when":"Sat Dec 19","q":"Will Tether's digital dollar lose ground to Circle's over the coming month?","cat":"Markets & business","label":"Stablecoin market-share shift","strength":"linked","instrument":"CRCL · Circle","yes":{"dir":"up","head":"Circle shares (CRCL)","why":"More USDC in circulation can increase the reserves Circle earns interest on. CRCL is the listed company exposed to that income."},"no":{"dir":"mixed","head":"Circle loses a potential tailwind","why":"If USDT retains its share, Circle loses the potential boost from taking share. CRCL can still benefit if the whole stablecoin market grows and USDC balances rise."},"caveat":"Lower rates or higher distribution costs can offset balance growth.","opt":"stocks:crcl"},{"id":"q_20261108_01","group":"Dec 14–20","when":"Until Sat Dec 19","q":"Will Congress approve new Iran war money before the December funding deadline?","cat":"Geopolitics","label":"Supplemental U.S. war funding","strength":"none","instrument":"Shares of contractors on funded programs","yes":{"dir":"mixed","head":"Contractors could gain if they win orders","why":"Specific defence companies benefit after approved funds turn into orders. The bill can also fund operations with little contractor upside."},"no":{"dir":"mixed","head":"Contractors lose a possible source of orders","why":"Without new funding, suppliers lose a possible source of extra orders. The share-price impact is small where contracts were already funded."},"caveat":"Funding can cover operations or stock replenishment with delayed awards.","opt":""},{"id":"q_20261107_04","group":"Dec 14–20","when":"Until Sun Dec 20","q":"Will Tesla hand its first Cybercab to a buyer by mid-December?","cat":"Tech & science","label":"First Tesla Cybercab delivery","strength":"linked","instrument":"TSLA · Tesla","yes":{"dir":"up","head":"Tesla shares (TSLA)","why":"A Cybercab delivery can move Tesla shares if it changes expectations for when mass production and revenue arrive."},"no":{"dir":"down","head":"Tesla shares (TSLA)","why":"If delivery slips, TSLA can fall if investors had counted on near-term commercialization. One delivery date can matter little to full-year volumes."},"caveat":"A single handover can already be priced in and may say little about future unit volumes.","opt":"stocks:tsla"},{"id":"q_20261114_04","group":"Dec 21–27","when":"Until Mon Dec 21","q":"Will Microsoft's Outlook or Teams suffer another major outage within five weeks?","cat":"Tech & science","label":"Microsoft service reliability","strength":"linked","instrument":"MSFT · Microsoft","yes":{"dir":"down","head":"Microsoft shares (MSFT)","why":"A prolonged outage can cost Microsoft money through customer credits or lost renewals. A short outage can leave MSFT largely unaffected."},"no":{"dir":"mixed","head":"Outage risk fades for MSFT","why":"Without a major outage, the outage-related credit and renewal risk recedes. MSFT is more likely to trade on cloud growth and margins."},"caveat":"A brief outage may have little effect on earnings.","opt":""},{"id":"q_20261116_02","group":"Dec 21–27","when":"Tue Dec 22","q":"Will Taiwan's November export orders top last year's by half?","cat":"Economy","label":"Taiwan export orders","strength":"proxy","instrument":"EWT · Taiwan equities","yes":{"dir":"up","head":"EWT","why":"A jump in chip export orders can lift earnings expectations for Taiwan’s chipmakers. EWT holds a broad basket of Taiwan stocks."},"no":{"dir":"down","head":"EWT","why":"If orders rise by less than expected, earnings expectations can cool, weighing on chip-heavy EWT. An already expected miss can have little effect."},"caveat":"US tech sentiment and currency moves can dominate the release.","opt":"etf:ewt"},{"id":"q_20261115_03","group":"Dec 21–27","when":"Until Wed Dec 23","q":"Will Congress pass new air traffic control money before Christmas?","cat":"Politics","label":"U.S. air traffic control funding","strength":"none","instrument":"Shares of FAA suppliers that win contracts","yes":{"dir":"mixed","head":"Winning FAA suppliers could gain","why":"Congress provides the funding first. Revenue reaches a specific company only after the FAA awards funded work to it."},"no":{"dir":"mixed","head":"Potential supplier orders move out","why":"If funding fails or slips, suppliers’ potential order growth moves out. Existing contracts can keep current sales steady."},"caveat":"Funding approval may precede revenue by years.","opt":""},{"id":"q_20261111_01","group":"Dec 21–27","when":"Until Wed Dec 23","q":"Will the International Monetary Fund approve Ukraine's next loan payment before Christmas?","cat":"Economy","label":"IMF payment to Ukraine","strength":"linked","instrument":"Ukraine government bonds","yes":{"dir":"up","head":"Ukrainian bond prices","why":"An IMF payment can add a financing buffer and support Ukrainian bond prices if the money is approved and disbursed."},"no":{"dir":"down","head":"Ukrainian bond prices","why":"If the IMF payment is delayed or rejected, a bigger near-term financing gap can weigh on Ukrainian bonds."},"caveat":"Wars and liquidity can overwhelm a single payment.","opt":""},{"id":"q_20261120_04","group":"Dec 21–27","when":"Until Thu Dec 24","q":"Will Congress pass the yearly defense bill before Christmas?","cat":"Geopolitics","label":"U.S. defense authorization","strength":"proxy","instrument":"ITA · U.S. aerospace and defense ETF","yes":{"dir":"up","head":"Defence stocks (ITA)","why":"The bill can direct more work toward contractors held by ITA. Actual revenue depends on appropriations and awards."},"no":{"dir":"mixed","head":"Defence orders could take longer","why":"If passage slips, ITA constituents face a slower path from authorization to awards. Existing funded work can cushion the delay."},"caveat":"Authorization and actual appropriations can arrive at different times.","opt":""},{"id":"q_20261123_03","group":"Dec 28–Jan 3","when":"Until Tue Dec 29","q":"Will South Korea let its refiners export more diesel?","cat":"Energy & climate","label":"Korean diesel export policy","strength":"proxy","instrument":"Asian gasoil vs crude","yes":{"dir":"down","head":"Asian diesel vs crude","why":"More Korean diesel shipments add regional supply and can compress diesel’s price premium over crude."},"no":{"dir":"mixed","head":"Diesel could keep its premium","why":"Without additional export permission, Asian diesel misses that source of fresh supply. Gasoil’s premium over crude can hold if demand remains strong."},"caveat":"Refinery downtime or stronger demand can outweigh the new cargoes.","opt":""},{"id":"q_20261120_02","group":"Dec 28–Jan 3","when":"Until Wed Dec 30","q":"Will Russia halt or cut its nitrogen fertilizer exports before year-end?","cat":"Energy & climate","label":"Russian nitrogen fertilizer exports","strength":"proxy","instrument":"CF · CF Industries","yes":{"dir":"up","head":"CF Industries shares (CF)","why":"Less Russian fertilizer supply can lift nitrogen prices. CF can benefit when its selling prices rise faster than natural gas costs."},"no":{"dir":"mixed","head":"CF loses a possible pricing boost","why":"If Russian exports continue, supply stays available to buyers. Nitrogen prices and CF’s margins get less support from this catalyst."},"caveat":"Natural gas costs and replacement supply can offset the pricing benefit.","opt":"stocks:cf"},{"id":"q_20261122_02","group":"Dec 28–Jan 3","when":"Until Thu Dec 31","q":"Will China's first fuel export quota for next year top this year's?","cat":"Energy & climate","label":"China fuel export quota","strength":"proxy","instrument":"Asian diesel and gasoline refining margins","yes":{"dir":"down","head":"Asian fuel prices","why":"A larger quota can put pressure on regional fuel prices if Chinese refiners use it to ship more product."},"no":{"dir":"mixed","head":"Asian refining margins could hold up","why":"If China issues a smaller or unchanged quota, Asian fuel markets get less extra supply. Regional refining margins can get support."},"caveat":"Quotas can go unused when export margins are weak.","opt":""},{"id":"q_20261121_02","group":"Dec 28–Jan 3","when":"Until Thu Dec 31","q":"Will Qatar plan next year's budget shortfall at double this year's?","cat":"Politics","label":"Qatar budget balance","strength":"proxy","instrument":"Qatar government bonds","yes":{"dir":"down","head":"Qatar bond prices","why":"A bigger deficit can make Qatar issue more debt, which can put pressure on bond prices if demand fails to keep up."},"no":{"dir":"up","head":"Qatar bond prices","why":"If the deficit is smaller, Qatar may need less new borrowing. That can support its government bonds if debt issuance actually falls."},"caveat":"Funding from reserves can limit relevant bond supply.","opt":""},{"id":"q_20261121_05","group":"Dec 28–Jan 3","when":"Until Thu Dec 31","q":"Will China tighten controls on rare earth or mineral exports this year?","cat":"Geopolitics","label":"China mineral export controls","strength":"proxy","instrument":"MP · MP Materials","yes":{"dir":"up","head":"MP Materials shares (MP)","why":"Chinese export restrictions can raise prices for competing rare-earth suppliers. MP’s exposure depends on which minerals are restricted."},"no":{"dir":"mixed","head":"MP loses a potential pricing boost","why":"Without tighter controls, the case for a shortage-driven rise in rare-earth prices weakens. MP loses that potential pricing boost."},"caveat":"Demand, contract pricing and processing capacity can break the link.","opt":"stocks:mp"},{"id":"q_20261120_03","group":"Dec 28–Jan 3","when":"Thu Dec 31","q":"Will Indian banks' gold loans shrink in November?","cat":"Markets & business","label":"Indian gold loan balances","strength":"proxy","instrument":"MUTHOOTFIN · Muthoot Finance","yes":{"dir":"down","head":"Muthoot shares","why":"A shrinking gold-loan market can slow originations and interest income at specialist lenders such as Muthoot Finance."},"no":{"dir":"up","head":"Muthoot shares","why":"If gold loans keep growing, more outstanding loans can support Muthoot’s interest income. Higher funding costs can still squeeze margins."},"caveat":"A smaller book can reflect repayment or slower origination.","opt":""},{"id":"q_20261120_05","group":"Dec 28–Jan 3","when":"Until Thu Dec 31","q":"Will a major Chinese cloud raise AI computing prices by late December?","cat":"Tech & science","label":"Chinese AI compute pricing, December","strength":"none","instrument":"Shares of the Chinese cloud provider that raises prices","yes":{"dir":"up","head":"Revenue at the provider raising prices","why":"Higher GPU rental prices can lift revenue for the provider if usage holds up. The company remains unspecified in the question."},"no":{"dir":"mixed","head":"Revenue growth relies more on usage","why":"If GPU rental prices stay flat, providers get less revenue per unit of compute from pricing. Growth then depends more on usage."},"caveat":"Discounts, capacity and electricity costs can erase the revenue change.","opt":""},{"id":"q_20261124_03","group":"Dec 28–Jan 3","when":"Thu Dec 31","q":"Will Tether's gold and bitcoin losses top half its cushion at year-end?","cat":"Markets & business","label":"Tether reserve cushion","strength":"proxy","instrument":"USDT/USD · Tether peg","yes":{"dir":"down","head":"USDT","why":"If Tether’s reserve loss exceeds half its cushion and prompts heavy redemptions, USDT could trade below $1."},"no":{"dir":"mixed","head":"Less pressure on the USDT peg","why":"If losses stay below half its cushion, pressure from that reserve shock eases. A sustained USDT discount would point to a separate concern."},"caveat":"A balance-sheet mark can change without causing a peg break.","opt":""},{"id":"q_20261122_01","group":"Dec 28–Jan 3","when":"Until Sun Jan 3","q":"Will war insurance cost more worldwide, not just in the Gulf?","cat":"Markets & business","label":"Global shipping insurance costs","strength":"proxy","instrument":"Tanker freight rates","yes":{"dir":"up","head":"Tanker freight rates","why":"Higher insurance premiums raise voyage costs. Freight rates can rise on routes where owners pass through the increase."},"no":{"dir":"mixed","head":"Higher freight costs could stay regional","why":"If insurance costs stay regional, tanker freight may reprice mainly on Gulf routes. The case for higher freight costs elsewhere weakens."},"caveat":"Cost pass-through varies by charter terms and vessel availability.","opt":""},{"id":"q_20261122_03","group":"Dec 28–Jan 3","when":"Until Sun Jan 3","q":"Will America renew Samsung's and SK Hynix's China factory permits before year-end?","cat":"Geopolitics","label":"Korean chipmakers' China permits","strength":"linked","instrument":"Samsung Electronics and SK Hynix","yes":{"dir":"up","head":"Samsung and SK Hynix shares","why":"The permits determine which China plants the two chipmakers can continue operating or upgrading. That can affect output and costs."},"no":{"dir":"down","head":"Samsung and SK Hynix shares","why":"Without renewals, the two chipmakers face more uncertainty around upgrades or operations in China. Higher costs or lower capacity can weigh on shares."},"caveat":"Restrictions on upgrades can persist after renewal.","opt":""},{"id":"q_20261123_05","group":"Jan 4–10","when":"Until Mon Jan 4","q":"Will America restart major bombing of Iran by early January?","cat":"Geopolitics","label":"Iran disruption risk","strength":"proxy","instrument":"ICE Brent crude futures","yes":{"dir":"up","head":"Brent oil","why":"Brent can rise if escalation disrupts oil exports or tanker transit and makes near-term supply scarcer."},"no":{"dir":"down","head":"Brent oil","why":"Without renewed bombing, Brent can lose some of its risk premium if tanker routes and export volumes look safer."},"caveat":"Risk premiums can unwind quickly if physical supply holds.","opt":""}];
